import * as THREE from 'three';

/**
 * Procedurally constructs AnimatedMorphCube (ANIMATED)
 * Bounding Box: [0.02, 0.02, 0.02] | Estimated Vertices: 24
 */
export function createAnimatedMorphCube(options = {}) {
  const {
    scale = 1.0,
    wireframe = false,
    emissiveIntensity = 1.5,
    castShadow = true,
    receiveShadow = true
  } = options;

  const rootGroup = new THREE.Group();
  rootGroup.name = "AnimatedMorphCube_Root";

  // Common PBR Materials tailored for animated
  const primaryMat = new THREE.MeshStandardMaterial({
    color: options.primaryColor || 0x2a3342,
    roughness: 0.35,
    metalness: 0.85,
    wireframe
  });

  const accentMat = new THREE.MeshStandardMaterial({
    color: options.accentColor || 0x00f0ff,
    emissive: 0x00f0ff,
    emissiveIntensity: emissiveIntensity,
    roughness: 0.2,
    metalness: 0.9,
    wireframe
  });

  const detailMat = new THREE.MeshStandardMaterial({
    color: 0x111317,
    roughness: 0.6,
    metalness: 0.4,
    wireframe
  });

  // Primary geometric structure
  const mainGeo = new THREE.BoxGeometry(0.016, 0.016, 0.016);
  const mainMesh = new THREE.Mesh(mainGeo, primaryMat);
  mainMesh.position.set(-0.000, -0.000, 0.000);
  mainMesh.castShadow = castShadow;
  mainMesh.receiveShadow = receiveShadow;
  rootGroup.add(mainMesh);

  // Accent & functional sub-elements
  const coreGeo = new THREE.CylinderGeometry(0.004, 0.005, 0.018, 16);
  const coreMesh = new THREE.Mesh(coreGeo, accentMat);
  coreMesh.position.set(-0.000, -0.000, 0.000);
  rootGroup.add(coreMesh);

  // Outer framing details
  const frameGeo = new THREE.TorusGeometry(0.008, 0.05, 8, 24);
  const frameMesh = new THREE.Mesh(frameGeo, detailMat);
  frameMesh.rotation.x = Math.PI / 2;
  frameMesh.position.set(-0.000, 0.004, 0.000);
  rootGroup.add(frameMesh);

  // Animation / Kinematics setup
  const mixer = new THREE.AnimationMixer(rootGroup);
  const trackTimes = [0, 1.0, 2.0];
  const rotValues = [0, 0, 0, 1,  0, 0.707, 0, 0.707,  0, 1, 0, 0];
  const rotTrack = new THREE.QuaternionKeyframeTrack('.quaternion', trackTimes, rotValues);
  const clip = new THREE.AnimationClip('Square', 2.0, [rotTrack]);
  const action = mixer.clipAction(clip);
  action.play();

  rootGroup.userData = {
    mixer,
    update: (delta) => mixer.update(delta),
    dimensions: new THREE.Vector3(0.020, 0.020, 0.020),
    center: new THREE.Vector3(-0.000, -0.000, 0.000)
  };

  rootGroup.scale.setScalar(scale);
  return rootGroup;
}
